import{_ as a,o,c as n,a3 as r}from"./chunks/framework.DMtjdCb-.js";const e="/help/assets/continue-watching.BULLH5e_.png",i="/help/assets/potplayer-weekly.BbXkK2w-.png",l="/help/assets/viewing-record.CAZjkk4V.png",m=JSON.parse('{"title":"6. 一键继续观看","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/continue-watching.md","filePath":"zh-Hans/continue-watching.md"}'),s={name:"zh-Hans/continue-watching.md"};function c(p,t,g,h,_,d){return o(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="_6-一键继续观看" tabindex="-1">6. 一键继续观看 <a class="header-anchor" href="#_6-一键继续观看" aria-label="Permalink to &quot;6. 一键继续观看&quot;">​</a></h1><p>一键继续观看把已订阅 TV 动画中有新集待看的作品整理成一份播放列表。每部从保存的续看集数开始，包含这一集，继续到当前可播放的最新一集。</p><h2 id="生成本次播放列表" tabindex="-1">生成本次播放列表 <a class="header-anchor" href="#生成本次播放列表" aria-label="Permalink to &quot;生成本次播放列表&quot;">​</a></h2><ol><li>打开 <strong>新作雷达</strong>，选择要观看的季度。</li><li>点击 <strong>一键继续观看</strong>，等待作品与集数列表出现。</li><li>勾选本次要看的作品。初始均未勾选，选中至少一部后播放按钮才可用。</li><li>拖动行前的手柄调整顺序；需要时调整某部作品的起止集数。</li><li>点击播放器按钮。最终列表仅包含勾选的作品，按界面从上到下排列。</li></ol><p><img src="'+e+'" alt="一键继续观看：勾选作品并拖动调整顺序" loading="lazy"></p><p><strong>完成标志：</strong> 播放器的播放列表包含选定作品及集数，按刚才的顺序连续播放。</p><p><img src="'+i+'" alt="PotPlayer 播放列表：连续观看多部作品" loading="lazy"></p><p>例如 A 续看第 3 集、可播放到第 4 集，B 续看第 4 集、可播放到第 5 集；先排 A 再排 B，列表就是 A 第 3–4 集、B 第 4–5 集。关闭播放器后，下次按实际取得的观看记录重新计算。</p><h2 id="理解浅绿色底纹" tabindex="-1">理解浅绿色底纹 <a class="header-anchor" href="#理解浅绿色底纹" aria-label="Permalink to &quot;理解浅绿色底纹&quot;">​</a></h2><p>浅绿色表示<strong>已订阅，且最新一集仍待看完</strong>。打开详情、把续看集数改成最新集数，都保留这项提示。</p><p>符合以下任意条件后，当前最新集视为已看完：</p><ul><li>点击 <strong>已看完最新集</strong>。</li><li>保存的续看集数大于当前最新集数。</li><li>PotPlayer 扩展回传最新一集的观看进度达到 <strong>90%</strong>。</li></ul><p>新集出现后会重新参与判断。暂停订阅、取消订阅或隐藏的作品不进入新生成的继续观看列表；已保存的观看记录仍保留。</p><h2 id="correct" tabindex="-1">手动纠正观看记录 <a class="header-anchor" href="#correct" aria-label="Permalink to &quot;手动纠正观看记录 {#correct}&quot;">​</a></h2><ol><li>点击雷达 <strong>已看集数</strong> 一列的数字，或作品详情中的观看记录入口。</li><li>输入下次开始观看的集数，需要时填写精确位置。</li><li>点击 <strong>保存</strong>。此记录会同步用于雷达和之后的播放列表。</li></ol><p><img src="'+l+'" alt="修改续看记录：保存集数、从头开始或确认最新集看完" loading="lazy"></p><p><strong>从头开始观看</strong> 清除续看状态；<strong>已看完最新集</strong> 用于明确确认看完；误改后可用窗口中的撤销操作恢复上一条记录。</p><p>播放列表未打开的部分不会因为“生成过列表”就被认定为看过。媒体访问推断可能受到播放器预读取影响，安装扩展后的精确反馈更可靠。</p>',18)])])}const f=a(s,[["render",c]]);export{m as __pageData,f as default};
